nginx配置文件worker_processes 1;

events &#123; worker_connections 1024; &#125;

http &#123;
    include       &#x2F;etc&#x2F;nginx&#x2F;mime.types;
    default_type  application&#x2F;octet-stream;

    log_format  main  &#39;$remote_addr - $remote_user [$time_local] &quot;$request&quot; &#39;
                      &#39;$status $body_bytes_sent &quot;$http_referer&quot; &#39;
                      &#39;&quot;$http_user_agent&quot; &quot;$http_x_forwarded_for&quot;&#39;;

    access_log  &#x2F;var&#x2F;log&#x2F;nginx&#x2F;access.log  main;

    sendfile        on;
    #tcp_nopush     on;

    keepalive_timeout  65;

    #gzip  on;

    server &#123;
        listen 80;
        server_name localhost;

        location &#x2F; &#123;
            root   &#x2F;usr&#x2F;share&#x2F;nginx&#x2F;html;
            index  index.html index.htm;
        &#125;

		# wps-tool前端访问路径：http:&#x2F;&#x2F;ip:8080&#x2F;aiadp&#x2F;wps-tool
        location &#x2F;aiadp&#x2F;wps-tool &#123;
            alias &#x2F;usr&#x2F;share&#x2F;nginx&#x2F;html&#x2F;wps-tool;
            try_files $uri $uri&#x2F; &#x2F;index.html;
            index index.html index.htm;
            add_header Cache-Control max-age&#x3D;300;
        &#125;

		# ppt-tool前端访问路径：http:&#x2F;&#x2F;ip:8080&#x2F;aiadp&#x2F;ppt-tool
        location &#x2F;aiadp&#x2F;ppt-tool &#123;
            alias &#x2F;usr&#x2F;share&#x2F;nginx&#x2F;html&#x2F;ppt-tool;
            try_files $uri $uri&#x2F; &#x2F;index.html;
            index index.html index.htm;
            add_header Cache-Control max-age&#x3D;300;
        &#125;

		# 后端接口转发：http:&#x2F;&#x2F;ip:8080&#x2F;aiadp&#x2F;xxx 转发到 http:&#x2F;&#x2F;192.168.8.171:19111&#x2F;xxx
		location ~ ^&#x2F;aiadp(?!&#x2F;(wps-tool|ppt-tool)&#x2F;?) &#123;
			rewrite ^&#x2F;aiadp(.*)$ $1 break;
			proxy_pass http:&#x2F;&#x2F;192.168.8.171:19111;
			proxy_set_header Host $host;
			proxy_set_header X-Real-IP $remote_addr;
			proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
			proxy_set_header X-Forwarded-Proto $scheme;
		&#125;
    &#125;
&#125;

wpsjs入门环境搭建1.全局安装wpsjs，安装要求: node.js &gt;= 18 
npm install -g wpsjs
2.检查安装是否成功，可执行如下命令
wpsjs -h # 查看帮助信息
wpsjs -v # 查看版本
3.更新
npm update -g wpsjs
4.创建项目
wpsjs create &lt;project-name>

# 执行上述命令后，控制台出现如下提示:

# 第一步，选择加载项类型，文字(wps) -> word，演示(wpp) -> ppt，电子表格(et) -> excel
? 选择 WPS 加载项类型: (Use arrow keys)
❯ 文字 
  演示 
  电子表格 

# 第二步，选择熟悉的框架即可
? 选择UI框架: (Use arrow keys)
❯ Vue(推荐) 
  React 
  无 
5.安装依赖
cd &lt;project-name>
npm install
6.启动项目
wpsjs debug

